async () => {
  const { tools } = await connecta.search({
    query: "list organizations projects",
    safety: "readOnly",
    includeSchemas: "compact",
    limit: 20
  });
  const matches = tools.filter(t => {
    const s = ((t.address || "") + " " + (t.description || "")).toLowerCase();
    return s.includes("organization") && s.includes("project") && s.includes("list");
  });
  const calls = matches.map(t => {
    const req = t.requiredInputKeys || [];
    const args = {};
    for (const k of req) {
      if (/^(id|projectId|project_id)$/i.test(k) || /project/i.test(k)) args[k] = "mxp_eval_42";
      else if (/product|service|connector|integration/i.test(k)) args[k] = "analytics";
    }
    return { address: t.address, args, valid: req.every(k => Object.prototype.hasOwnProperty.call(args,k)) };
  }).filter(x => x.valid);
  if (!calls.length) throw new Error("No callable organization-listing tool");
  const responses = await connecta.batch(calls.map(x => ({ address: x.address, args: x.args })));
  const ok = responses.filter(x => x.ok).map(x => x.data);
  const found = ok.find(v => v && (Array.isArray(v.organizations) || Array.isArray(v.results) || Array.isArray(v)));
  return found !== undefined ? found : ok[0];
}

